import '../App.css';
import './EstiloSesiones.css';
import { useNavigate } from 'react-router-dom';
import { useState, useRef, useEffect } from 'react';
import { loginUsuario, setAuthToken, setUsuario } from '../services/api';

function InicioSesion() {
  const [formData, setFormData] = useState({
    correo: '',
    contrasena: ''
  });
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const navigate = useNavigate();
  const menuRef = useRef(null);

  const [idioma, setIdioma] = useState('es');
  const [menuAbierto, setMenuAbierto] = useState(false);
  const [modalActivo, setModalActivo] = useState(null);

  const textos = {
    es: {
      espanyol: 'Español',
      ingles: 'Inglés',
      ayudaP1: 'Introduce tus credenciales para acceder a tu cuenta.',
      ayudaP2: 'Si no tienes cuenta, ve a la página principal y regístrate.',
      acercaH5: 'CaffES App v1.0',
      acercaP: 'IES José Zerpa'
    },
    en: {
      titulo: 'Login',
      correo: 'Email:',
      contrasena: 'Password:',
      volver: 'Back',
      confirmar: 'Confirm',
      cargando: 'Loading...',
      idioma: 'Language',
      ayuda: 'Help',
      acerca: 'About',
      cerrar: 'Close',
      espanyol: 'Spanish',
      ingles: 'English',
      ayudaP1: 'Enter your credentials to access your account.',
      ayudaP2: 'If you do not have an account, go to the main page and register.',
      acercaH5: 'CaffES App v1.0',
      acercaP: 'IES José Zerpa'
    }
  };

  const t = textos[idioma];

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    setLoading(true);

    try {
      const response = await loginUsuario(formData);
      setAuthToken(response.data.token);
      setUsuario(response.data.usuario);
      navigate('/home');
    } catch (error) {
      setError(error.response?.data?.error || 'Error en el servidor');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    const handleClickAfuera = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        setMenuAbierto(false);
      }
    };
    document.addEventListener('mousedown', handleClickAfuera);
    return () => document.removeEventListener('mousedown', handleClickAfuera);
  }, []);

  return (
    <div className="App">
      <header className="App-header">
        <div className="header-container">
          <div className="title">{t.titulo}</div>
          <div className="header-right">
            <div className="user-menu-wrapper" ref={menuRef}>
              <button className="hamburger-btn" onClick={() => setMenuAbierto(!menuAbierto)}>
                <span></span>
                <span></span>
                <span></span>
              </button>
              {menuAbierto && (
                <div className="user-dropdown session-dropdown shadow-lg">
                  <button className="dropdown-item" onClick={() => { setModalActivo('idioma'); setMenuAbierto(false); }}>
                    {t.idioma}
                  </button>
                  <button className="dropdown-item" onClick={() => { setModalActivo('ayuda'); setMenuAbierto(false); }}>
                    {t.ayuda}
                  </button>
                  <button className="dropdown-item" onClick={() => { setModalActivo('acerca'); setMenuAbierto(false); }}>
                    {t.acerca}
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </header>

      {modalActivo && (
        <div className="prefs-overlay">
          <div className="prefs-modal shadow-lg">
            <h3>{t[modalActivo]}</h3>
            <div className="modal-content-area">
              {modalActivo === 'idioma' && (
                <div className="prefs-section">
                  <label>{t.idioma}</label>
                  <div className="btn-group-toggle">
                    <button className={idioma === 'es' ? 'active' : ''} onClick={() => setIdioma('es')}>
                      {t.espanyol} 🇪🇸
                    </button>
                    <button className={idioma === 'en' ? 'active' : ''} onClick={() => setIdioma('en')}>
                      {t.ingles} 🇬🇧
                    </button>
                  </div>
                </div>
              )}
              {modalActivo === 'ayuda' && (
                <div className="help-info text-center">
                  <p>{t.ayudaP1}</p>
                  <p className="small text-white-50">{t.ayudaP2}</p>
                </div>
              )}
              {modalActivo === 'acerca' && (
                <div className="text-center">
                  <h5 className="text-warning">{t.acercaH5}</h5>
                  <p className="small">{t.acercaP}</p>
                </div>
              )}
            </div>
            <button className="btn-confirm-prefs mt-4" onClick={() => setModalActivo(null)}>
              {t.cerrar}
            </button>
          </div>
        </div>
      )}

      <main className="App-main">
        <div className="cont_sesion">
          <form className='form-cont' onSubmit={handleSubmit}>
            {error && (
              <div className="alert alert-danger" style={{ color: 'red', marginBottom: '15px' }}>
                {error}
              </div>
            )}

            <div className="form-group">
              <label>{t.correo}</label>
              <input
                type="email"
                name="correo"
                value={formData.correo}
                onChange={handleChange}
                required
              />
            </div>
            <div className="form-group">
              <label>{t.contrasena}</label>
              <input
                type="password"
                name="contrasena"
                value={formData.contrasena}
                onChange={handleChange}
                required
              />
            </div>
            <div className="btn-container">
              <button
                type="button"
                className="btn-volver"
                onClick={() => navigate('/')}
                disabled={loading}
              >
                {t.volver}
              </button>
              <button
                type="submit"
                className="btn-confirmar"
                disabled={loading}
              >
                {loading ? t.cargando : t.confirmar}
              </button>
            </div>
          </form>
        </div>
      </main>
      <footer className="App-footer">
        <div>© IES José Zerpa - Cafetería</div>
      </footer>
    </div>
  );
}

export default InicioSesion;
